import {requestAutoStop,readAutoStop,createAutoStopWatcher} from './full-auto-control.js';
import {autoJobs,createFullAutoJob,estimateFullAutoCost,runFullAuto} from './full-auto.js';
const esc=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const button=(label,action,id,kind='outline')=>`<button type="button" class="btn btn-${kind}" data-full-auto-action="${action}" ${id?`data-id="${esc(id)}"`:''}>${label}</button>`;
let api,controller=null,currentJob=null,inspectedId=null,configured=false;
export const isFullAutoRunning=()=>!!controller;
export function cleanupFullAuto(hide=false){if(hide===true){inspectedId=null;return;}controller?.abort();}
export function renderFullAutoLauncher(state,wizard){const estimate=estimateFullAutoCost(state,wizard);return `<section class="full-auto-launcher" aria-label="FULL AUTO MODE"><div><span class="role-tag">FULL AUTO MODE</span><h3>주제만 적고, 한 권을 한 번에</h3><p>고른 친구를 주인공으로 유지해요. 필요한 친구·장소는 서랍에서 고르고, 부족하면 새 시트부터 본문 그림과 표지까지 자동으로 만들어요.</p></div><label class="audio-cache-check"><input id="full-auto-allow-new" type="checkbox" checked> 부족한 재료 자동 추가 · 새 조연 최대 2명, 새 배경 최대 3곳</label><p class="small-label">${estimate.pageCount}쪽 · 부모 설정의 글·그림 엔진과 읽기 수준 사용<br>API 예상 약 $${estimate.baseUsd.toFixed(2)} · 새 시트와 유사 그림 재생성까지 약 $${estimate.withMaterialsAndRetryUsd.toFixed(2)}<br>참고 단가 추정이며 실제 한도가 아닙니다. 글 자동 수정·입력 참조 비용 별도.${estimate.imageEngine==='sample'?'<br>현재 그림 엔진은 무료 고정 샘플입니다. AI 그림은 부모 설정에서 엔진을 변경해 주세요.':''}</p><p class="small-label">완료 후 전체 초안을 검토해 책장에 저장해요. 제작 중에도 책장을 둘러볼 수 있어요. 브라우저를 완전히 종료하면 완료한 결과를 보관하고 다음 접속에서 이어 만들어요.</p>${button('FULL AUTO 실행 · 예상 비용 확인','start',null,'primary')}</section>`;}
export function renderFullAutoJobs(state){const jobs=Object.values(state.fullAutoJobs||{}).filter(j=>j?.id&&j.status!=='final').sort((a,b)=>String(b.updatedAt).localeCompare(String(a.updatedAt)));if(!jobs.length)return '';return `<section class="panel full-auto-jobs" id="full-auto-jobs"><h3>제작 중인 이야기</h3><div class="story-drafts">${jobs.map(job=>{
 const live=currentJob?.id===job.id&&!!controller,pending=readAutoStop(job.id),requested=pending?.nonce&&pending.nonce!==job.stopBaselineNonce&&job.status!=='paused';
 return `<article class="story-draft-card" data-auto-job="${esc(job.id)}"><span class="role-tag">FULL AUTO · ${job.status==='review'?'완성 초안':requested?'중지 요청됨':live?'제작 중':job.status==='running'?'마지막 저장 내역':'대기'}</span><strong>${esc(job.book?.title||job.input?.topic)}</strong><p>${esc(job.phase||'준비')} · ${job.book?.pages?.filter(p=>p.imageAssetId).length||0} / ${job.input?.pageCount||12}쪽 그림</p>${job.status==='running'&&!live?'<p class="small-label">이 화면에서는 실행 중이 아닙니다. 이어 만들거나 중지할 수 있어요.</p>':''}${job.error?`<p class="pin-error">${esc(job.error)}</p>`:''}<div class="story-inline-actions">${job.status==='review'?button('완성 초안 검토','review',job.id,'green'):live?button('진행 상황','status',job.id):button('이어서 만들기','resume',job.id,'green')}${job.status!=='review'?button('중지','pause',job.id):''}${job.book&&job.status!=='review'&&!live?button('완료된 부분 검토','review',job.id):''}</div></article>`;}).join('')}</div></section>`;}
function refreshCards(){const slot=document.querySelector('#full-auto-jobs');if(slot)slot.outerHTML=renderFullAutoJobs(api.getState());}

function runScreen(job,busy){inspectedId=job.id;const plan=job.plan,images=job.book?.pages?.filter(p=>p.imageAssetId).length||0,textCalls=job.usage.calls.reduce((n,c)=>n+(Number(c.requests)||0),0),imageCalls=Object.keys(job.imageUsage||{}).length;api.showModal(`${api.modalHeader('FULL AUTO · '+(job.status==='review'?'완성 초안':'이야기 만드는 중'))}<p class="modal-intro">${esc(job.input.topic)}</p><p id="full-auto-progress" class="notice" role="status" aria-live="polite">${esc(job.phase)}</p><p id="full-auto-count" class="small-label">그림 ${images} / ${job.input.pageCount}쪽 · 글 요청 ${textCalls}회 · 저장된 생성 이미지 ${imageCalls}장</p>${plan?`<details class="story-card"><summary>자동으로 고른 재료</summary><p>등장인물: ${plan.characterIds.map(id=>esc(api.getState().characters.find(c=>c.id===id)?.name||plan.newCharacters.find(c=>c.id===id)?.name)).join(' · ')}</p><p>장소: ${plan.backgroundIds.map(id=>esc(api.getState().backgrounds.find(b=>b.id===id)?.name||plan.newBackgrounds.find(b=>b.id===id)?.name)).join(' · ')}</p><p>${esc(plan.reason)}</p><p class="small-label">새 조연 ${plan.newCharacters.length}명 · 새 배경 ${plan.newBackgrounds.length}곳 · 자동 생성 시트는 완료 후 함께 검토해 주세요.</p></details>`:''}<ol class="full-auto-steps">${[['plan','재료 선택'],['input','시트 준비'],['outline','줄거리'],['briefs','장면 디테일'],['prose','한영 전문'],['enrichment','글 풍부화'],['pagination','쪽 나누기'],['cover','본문 그림·표지']].map(([key,label])=>`<li class="${job.completed[key]?'done':''}">${job.completed[key]?'✓':'○'} ${label}</li>`).join('')}</ol>${job.error?`<p class="pin-error">${esc(job.error)}</p>`:''}${job.notes.map(n=>`<p class="small-label">${esc(n)}</p>`).join('')}<p class="small-label">완료한 재료·문단·그림은 저장됩니다. 이 창을 닫아도 제작은 계속됩니다. 브라우저를 완전히 종료하면 다음 접속에서 이어 만들어요. 최종 검토 전에는 아이 책장에 공개되지 않습니다.</p><div class="modal-actions">${busy?button('닫고 둘러보기','close',job.id)+button('중지 · 결과 보관','pause',job.id):job.status==='review'?button('완성 초안 검토','review',job.id,'primary'):button('이어서 자동 생성','resume',job.id,'primary')}${!busy?button('닫기','close',job.id):''}</div>`,'wide full-auto-workspace');}
async function execute(job){
 if(controller){api.toast('이미 제작 중인 작업이 있어요. 책장에서 진행 상태를 확인해 주세요.');return;}
 const state=api.getState(),operation=new AbortController();controller=operation;currentJob=job;inspectedId=null;job.stopBaselineNonce=readAutoStop(job.id)?.nonce||null;
 const watcher=createAutoStopWatcher(job.id,{accountId:api.getCloudAccount?.(),onStop:row=>{job.stopRequestedAt=row.requestedAt;job.stopAcknowledgedNonce=row.nonce;operation.abort();}});
 const work=async()=>{if(job.status==='running')job.status='paused';await watcher.start();return runFullAuto(state,job,{signal:operation.signal,save:()=>{watcher.check();if(api.getState()!==state||!api.isParent()){operation.abort();throw new DOMException('부모 작업을 중지했어요.','AbortError');}return api.save();},buildBook:api.buildBook,onProgress:({message})=>{if(currentJob!==job||operation.signal.aborted)return;refreshCards();if(inspectedId!==job.id||!document.querySelector('.full-auto-workspace'))return;const progress=document.querySelector('#full-auto-progress'),count=document.querySelector('#full-auto-count');if(progress)progress.textContent=message;if(count)count.textContent=`그림 ${job.book?.pages?.filter(p=>p.imageAssetId).length||0} / ${job.input.pageCount}쪽 · 글 요청 ${job.usage.calls.reduce((n,c)=>n+(Number(c.requests)||0),0)}회`;}});};
 api.onStarted?.(job);api.toast('제작을 시작했어요. 책장의 제작 카드에서 진행 확인·중지를 할 수 있어요.');
 try{if(globalThis.navigator?.locks)await navigator.locks.request('donghwa-full-auto-'+job.id,{ifAvailable:true},lock=>{if(!lock)throw Error('다른 탭에서 이 자동 작업이 실행 중이에요. 그 탭에서 이어 주세요.');return work();});else await work();if(api.getState()===state&&api.isParent())api.toast('이야기가 완성됐어요. 책장에서 완성 초안을 검토해 주세요.');}
 catch(error){if(api.getState()===state&&api.isParent())api.toast(error.name==='AbortError'?'제작을 중지하고 완료한 결과를 보관했어요.':error.message);}
 finally{watcher.close();if(controller===operation){controller=null;currentJob=null;if(api.getState()===state&&api.isParent()){refreshCards();if(inspectedId===job.id&&document.querySelector('.full-auto-workspace'))runScreen(job,false);}}}
}
async function stopJob(job){
 const running=currentJob?.id===job.id&&!!controller;if(running)controller.abort();
 const response=await requestAutoStop(job.id,{accountId:api.getCloudAccount?.()});
 if(!running&&job.status!=='running'){job.status='paused';job.phase='중지 · 완료한 결과 보관';job.stopRequestedAt=response.requestedAt;api.save();}
 refreshCards();api.toast(response.remoteError?`이 브라우저에 중지를 반영했어요. ${response.remoteError}`:response.remoteStored?'중지 요청을 저장했어요. 실행 중인 기기에 전달됩니다.':'중지 요청을 보관했어요. 완료한 결과는 유지됩니다.');
}

export function configureFullAutoUI(context){api=context;if(configured)return;configured=true;document.addEventListener('click',event=>{const el=event.target.closest('[data-full-auto-action]');if(!el)return;event.preventDefault();api.protectedAction(async()=>{try{const action=el.dataset.fullAutoAction;if(action==='close'){api.closeModal();return;}const state=api.getState();if(action==='start'){if(controller)return api.toast('현재 자동 작업이 실행 중이에요.');const wizard=api.getWizard(),allowNew=document.querySelector('#full-auto-allow-new')?.checked!==false,job=createFullAutoJob(state,wizard,{allowNew});if(api.save()===false){delete autoJobs(state)[job.id];throw Error('자동 작업을 저장하지 못했어요.');}await execute(job);return;}const job=autoJobs(state)[el.dataset.id];if(!job)throw Error('자동 작업을 찾지 못했어요.');if(action==='pause'){await stopJob(job);return;}if(action==='status'){runScreen(job,currentJob?.id===job.id&&!!controller);return;}if(action==='resume'){await execute(job);return;}if(action==='review'){if(controller)throw Error('실행 중인 작업을 먼저 중지해 주세요.');if(!job.book)throw Error('아직 그림 단계의 초안이 없어요. 자동 생성을 이어 주세요.');await api.openReview(job);}}catch(error){api.toast(error.message);}});});globalThis.window?.addEventListener('pagehide',cleanupFullAuto);}
